package httpapi

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"time"

	"github.com/hkjang/jikim/internal/tracking"
)

// cspReportPath is where browsers post the requests the content security
// policy refused. It is unauthenticated because the browser sends the report
// without credentials, and it keeps nothing but a bounded list of origins in
// memory.
const cspReportPath = "/api/v1/tracking/csp-report"

// maxCSPReportBytes keeps an unauthenticated endpoint from being used to push
// large bodies at the server.
const maxCSPReportBytes = 8 * 1024

// maxMomentoProxyBytes bounds one forwarded event batch. A page view is a few
// hundred bytes; the limit exists so the proxy cannot be used as a relay.
const maxMomentoProxyBytes = 64 * 1024

// basePagePolicy is the policy every screen has always shipped with. Tracking
// adds to it per request; it never replaces or loosens it.
const (
	basePagePolicy = "default-src 'self'; script-src 'self'%s; style-src 'self' 'unsafe-inline'; img-src 'self' data:%s; connect-src 'self'%s; font-src 'self' data:; frame-ancestors 'none'"
	// apiPolicy is for responses no browser renders: JSON, SSE, the proxy.
	// Nothing in them may load anything, so the policy says so.
	apiPolicy = "default-src 'none'; frame-ancestors 'none'"
)

type nonceKey struct{}

// requestNonce returns the per-request script nonce the page handler minted,
// or "" for requests that never render a page.
func requestNonce(r *http.Request) string {
	value, _ := r.Context().Value(nonceKey{}).(string)
	return value
}

func newNonce() string {
	raw := make([]byte, 16)
	if _, err := rand.Read(raw); err != nil {
		return ""
	}
	return base64.RawURLEncoding.EncodeToString(raw)
}

// pagePath reports whether a request path is one a browser renders as a
// screen. Everything else gets the narrow policy.
func pagePath(path string) bool {
	if strings.HasPrefix(path, "/api/") || strings.HasPrefix(path, "/v1/") || path == "/mcp" ||
		path == "/healthz" || path == "/readyz" || strings.HasPrefix(path, mcpOAuthMetadataPath) {
		return false
	}
	return path != tracking.MomentoProxyPrefix && !strings.HasPrefix(path, tracking.MomentoProxyPrefix+"/")
}

// pagePolicy keeps the strict page policy and adds only what the configured
// snippet needs: the nonce for its inline code and the origins it talks to.
func pagePolicy(config tracking.Config, path, nonce string) string {
	if !config.Active(path) || nonce == "" {
		return defaultPagePolicy()
	}
	scripts, connects, images := config.PolicySources()
	scripts = append([]string{"'nonce-" + nonce + "'"}, scripts...)
	policy := fmt.Sprintf(basePagePolicy, join(scripts), join(images), join(connects))
	// While tracking is on, ask the browser to say what it refused. That
	// report is what turns a console error into a one-click fix.
	return policy + "; report-uri " + cspReportPath
}

// defaultPagePolicy is the policy with nothing added: the one every screen
// gets while tracking is off, byte for byte what shipped before tracking.
func defaultPagePolicy() string {
	return fmt.Sprintf(basePagePolicy, "", "", "")
}

func join(sources []string) string {
	if len(sources) == 0 {
		return ""
	}
	return " " + strings.Join(sources, " ")
}

// trackingConfig reads the tracking setting. A storage failure is treated as
// "tracking off" so an outage never keeps the login screen from loading.
func (s *Server) trackingConfig(ctx context.Context) tracking.Config {
	if s.trackingLoader == nil {
		return tracking.ReadConfig(nil)
	}
	config, err := s.trackingLoader(ctx)
	if err != nil {
		s.logger.Warn("방문 추적 설정을 읽지 못해 이번 응답은 추적 없이 보냅니다", "error", err)
		return tracking.ReadConfig(nil)
	}
	return config
}

// decorateIndex is applied to the SPA shell only. It mints the nonce, sets the
// page policy that names it, and injects the snippet carrying it, so the
// header and the markup always agree.
func (s *Server) decorateIndex(w http.ResponseWriter, r *http.Request, page []byte) []byte {
	config := s.trackingConfig(r.Context())
	if !config.Active(r.URL.Path) {
		return page
	}
	nonce := newNonce()
	if nonce == "" {
		return page
	}
	*r = *r.WithContext(context.WithValue(r.Context(), nonceKey{}, nonce))
	w.Header().Set("Content-Security-Policy", pagePolicy(config, r.URL.Path, nonce))
	return tracking.Inject(page, config.Snippet(nonce), config.Placement)
}

type cspReport struct {
	Report struct {
		BlockedURI         string `json:"blocked-uri"`
		ViolatedDirective  string `json:"violated-directive"`
		EffectiveDirective string `json:"effective-directive"`
		DocumentURI        string `json:"document-uri"`
	} `json:"csp-report"`
}

// receiveCSPReport records what a browser refused to load. Reports are always
// answered with 204 so a misbehaving page never sees an error from us.
func (s *Server) receiveCSPReport(w http.ResponseWriter, r *http.Request) {
	defer w.WriteHeader(http.StatusNoContent)
	if s.violations == nil {
		return
	}
	// While tracking is off no page was ever given the report-uri, so a report
	// arriving here came from outside the browser. Recording it would let anyone
	// fill the administrator's blocked-origins list on a fresh install.
	if !s.trackingConfig(r.Context()).ReportingActive() {
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, maxCSPReportBytes))
	if err != nil || len(body) == 0 {
		return
	}
	var report cspReport
	if json.Unmarshal(body, &report) != nil {
		return
	}
	directive := report.Report.EffectiveDirective
	if directive == "" {
		directive = report.Report.ViolatedDirective
	}
	s.violations.Record(report.Report.BlockedURI, directive, report.Report.DocumentURI)
}

// listTrackingViolations shows the administrator which addresses the policy
// is blocking, so a snippet can be fixed without reading the browser console.
func (s *Server) listTrackingViolations(w http.ResponseWriter, r *http.Request) {
	items := []tracking.Violation{}
	if s.violations != nil {
		items = s.violations.List(s.trackingConfig(r.Context()))
	}
	writeData(w, http.StatusOK, items)
}

// clearTrackingViolations forgets the recorded reports, which is how an
// administrator checks whether a change actually fixed the snippet.
func (s *Server) clearTrackingViolations(w http.ResponseWriter, r *http.Request) {
	if s.violations != nil {
		s.violations.Forget()
	}
	w.WriteHeader(http.StatusNoContent)
}

// allowTrackingOrigin adds one blocked origin to the allow list. It is the
// one-click fix for the reports listed above.
func (s *Server) allowTrackingOrigin(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Origin string `json:"origin"`
	}
	if !decodeJSON(w, r, &input) {
		return
	}
	config, err := s.trackingLoader(r.Context())
	if err != nil {
		s.storeError(w, r, err)
		return
	}
	hosts, ok := tracking.AddAllowedHost(config.AllowedHosts, input.Origin)
	if !ok {
		writeError(w, r, http.StatusBadRequest, "invalid_origin", "허용할 출처는 http(s) 주소여야 합니다")
		return
	}
	session, _ := sessionFrom(r)
	if err := s.store.PatchSetting(r.Context(), "tracking", map[string]any{"allowed_hosts": hosts}, session.User.ID); err != nil {
		s.storeError(w, r, err)
		return
	}
	writeData(w, http.StatusOK, map[string]any{"allowed_hosts": hosts})
}

// momentoProxy forwards /momento/* to the collector so the browser only ever
// talks to this origin. It answers 404 unless Momento is on with the proxy
// chosen, so a fresh install exposes nothing.
func (s *Server) momentoProxy(w http.ResponseWriter, r *http.Request) {
	config := s.trackingConfig(r.Context())
	if !config.ProxyActive() {
		writeError(w, r, http.StatusNotFound, "not_found", "요청한 경로를 찾을 수 없습니다")
		return
	}
	if r.Method != http.MethodGet && r.Method != http.MethodHead && r.Method != http.MethodPost {
		writeError(w, r, http.StatusMethodNotAllowed, "method_not_allowed", "허용되지 않은 요청 방식입니다")
		return
	}
	target, err := url.Parse(strings.TrimRight(strings.TrimSpace(config.MomentoURL), "/"))
	if err != nil || target.Host == "" {
		writeError(w, r, http.StatusBadGateway, "bad_gateway", "Momento 수집기 주소가 올바르지 않습니다")
		return
	}
	proxy := &httputil.ReverseProxy{
		Rewrite: func(request *httputil.ProxyRequest) {
			request.SetURL(target)
			request.SetXForwarded()
			request.Out.URL.Path = target.Path + strings.TrimPrefix(r.URL.Path, tracking.MomentoProxyPrefix)
			request.Out.URL.RawPath = ""
			request.Out.Host = target.Host
			// The collector is not this application: it must not see the
			// session cookie or a bearer token the browser attached.
			request.Out.Header.Del("Cookie")
			request.Out.Header.Del("Authorization")
			request.Out.Header.Del("X-Vault-Token")
		},
		Transport:     s.httpClient.Transport,
		FlushInterval: -1,
		ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
			s.logger.Warn("Momento 수집기에 전달하지 못했습니다", "error", err, "request_id", requestIDFrom(r))
			writeError(w, r, http.StatusBadGateway, "bad_gateway", "Momento 수집기에 연결할 수 없습니다")
		},
		ModifyResponse: func(response *http.Response) error {
			// Whatever the collector says, the browser must not get cookies
			// or a policy from another origin under our name.
			response.Header.Del("Set-Cookie")
			response.Header.Del("Content-Security-Policy")
			return nil
		},
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxMomentoProxyBytes)
	ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()
	proxy.ServeHTTP(w, r.WithContext(ctx))
}
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/hkjang/jikim/internal/model"
	"github.com/hkjang/jikim/internal/tracking"
)

// shippedPolicy is the header every screen carried before tracking existed.
// A fresh install, and an install that switched tracking off again, must send
// exactly this.
const shippedPolicy = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; font-src 'self' data:; frame-ancestors 'none'"

const shellPage = "<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<title>jikim</title>\n</head>\n<body>\n<div id=\"root\"></div>\n<script type=\"module\" src=\"/assets/index.js\"></script>\n</body>\n</html>\n"

var noncePattern = regexp.MustCompile(`'nonce-([A-Za-z0-9_-]+)'`)

// trackingServer builds a Server that serves a throwaway SPA shell and reads
// its tracking configuration from the given loader instead of PostgreSQL.
func trackingServer(t *testing.T, config tracking.Config, loadErr error) (*Server, http.Handler) {
	t.Helper()
	root := t.TempDir()
	if err := os.WriteFile(filepath.Join(root, "index.html"), []byte(shellPage), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "asset.js"), []byte("console.log(1)"), 0o600); err != nil {
		t.Fatal(err)
	}
	server := quietServer()
	server.violations = tracking.NewRecorder()
	server.storagePinger = func(context.Context) error { return nil }
	server.trackingLoader = func(context.Context) (tracking.Config, error) { return config, loadErr }
	server.static = &spaHandler{root: root, fileServer: http.FileServer(http.Dir(root)), decorate: server.decorateIndex}
	mux := http.NewServeMux()
	server.routes(mux)
	return server, server.securityHeaders(mux)
}

func momentoConfig() tracking.Config {
	return tracking.ReadConfig(map[string]any{
		"enabled": true, "provider": "momento",
		"momento_url": "https://momento.corp.example", "momento_site_id": "jikim-prod",
	})
}

func getPage(handler http.Handler, path string) *httptest.ResponseRecorder {
	response := httptest.NewRecorder()
	handler.ServeHTTP(response, httptest.NewRequest(http.MethodGet, path, nil))
	return response
}

func TestFreshInstallServesTheShippedPolicyAndNoSnippet(t *testing.T) {
	_, handler := trackingServer(t, tracking.ReadConfig(nil), nil)
	for _, path := range []string{"/", "/dashboard", "/login", "/admin/settings"} {
		response := getPage(handler, path)
		if response.Code != http.StatusOK {
			t.Fatalf("%s status=%d", path, response.Code)
		}
		if got := response.Header().Get("Content-Security-Policy"); got != shippedPolicy {
			t.Fatalf("%s policy changed on a fresh install:\n%s", path, got)
		}
		if strings.Contains(response.Body.String(), "nonce=") || strings.Contains(response.Body.String(), "tracker.js") {
			t.Fatalf("%s carried a snippet while tracking is off: %s", path, response.Body.String())
		}
	}
	// The proxy path is closed too: nothing is exposed until Momento is on.
	response := getPage(handler, "/momento/tracker.js")
	if response.Code != http.StatusNotFound {
		t.Fatalf("proxy answered %d while tracking is off", response.Code)
	}
}

func TestEnabledTrackingCarriesANoncedSnippetAndAMatchingPolicy(t *testing.T) {
	_, handler := trackingServer(t, momentoConfig(), nil)
	first := getPage(handler, "/dashboard")
	second := getPage(handler, "/dashboard")
	for _, response := range []*httptest.ResponseRecorder{first, second} {
		policy := response.Header().Get("Content-Security-Policy")
		match := noncePattern.FindStringSubmatch(policy)
		if match == nil {
			t.Fatalf("policy has no nonce: %s", policy)
		}
		scriptSrc := strings.SplitN(strings.SplitN(policy, "script-src ", 2)[1], ";", 2)[0]
		if strings.Contains(scriptSrc, "unsafe-inline") || strings.Contains(scriptSrc, "unsafe-eval") {
			t.Fatalf("script-src must not be loosened: %s", policy)
		}
		if !strings.HasSuffix(policy, "; report-uri "+cspReportPath) {
			t.Fatalf("policy lacks report-uri: %s", policy)
		}
		if strings.Contains(policy, "momento.corp.example") {
			t.Fatalf("proxied Momento leaked the collector into the policy: %s", policy)
		}
		body := response.Body.String()
		wantTag := `<script nonce="` + match[1] + `" async src="/momento/tracker.js" data-site-id="jikim-prod"`
		if !strings.Contains(body, wantTag) {
			t.Fatalf("snippet missing or nonce mismatched:\npolicy=%s\nbody=%s", policy, body)
		}
		if !strings.Contains(body, `data-endpoint="/momento"`) {
			t.Fatalf("proxied snippet lacks data-endpoint: %s", body)
		}
		head := strings.SplitN(body, "</head>", 2)[0]
		if !strings.Contains(head, wantTag) {
			t.Fatalf("head placement put the snippet elsewhere: %s", body)
		}
	}
	if noncePattern.FindStringSubmatch(first.Header().Get("Content-Security-Policy"))[1] == noncePattern.FindStringSubmatch(second.Header().Get("Content-Security-Policy"))[1] {
		t.Fatal("nonce was reused across requests")
	}
}

func TestCustomSnippetOriginsAndBodyPlacement(t *testing.T) {
	config := tracking.ReadConfig(map[string]any{
		"enabled": true, "provider": "custom", "placement": "body",
		"custom_snippet": `<script src="https://t.corp.example/t.js"></script><script>window.__t={e:"https://c.corp.example/collect"}</script>`,
		"allowed_hosts":  "https://pixel.corp.example",
	})
	_, handler := trackingServer(t, config, nil)
	response := getPage(handler, "/secrets")
	policy := response.Header().Get("Content-Security-Policy")
	scriptSrc := strings.SplitN(strings.SplitN(policy, "script-src ", 2)[1], ";", 2)[0]
	connectSrc := strings.SplitN(strings.SplitN(policy, "connect-src ", 2)[1], ";", 2)[0]
	imgSrc := strings.SplitN(strings.SplitN(policy, "img-src ", 2)[1], ";", 2)[0]
	for _, origin := range []string{"https://t.corp.example", "https://c.corp.example", "https://pixel.corp.example"} {
		for name, directive := range map[string]string{"script-src": scriptSrc, "connect-src": connectSrc, "img-src": imgSrc} {
			if !strings.Contains(directive, origin) {
				t.Fatalf("%s lacks %s: %s", name, origin, policy)
			}
		}
	}
	body := response.Body.String()
	nonce := noncePattern.FindStringSubmatch(policy)[1]
	if strings.Count(body, `nonce="`+nonce+`"`) != 2 {
		t.Fatalf("both script tags need the nonce: %s", body)
	}
	tail := strings.SplitN(body, "</head>", 2)[1]
	if !strings.Contains(tail, `nonce="`+nonce+`" src="https://t.corp.example/t.js"`) || !strings.Contains(strings.SplitN(tail, "</body>", 2)[0], "t.corp.example") {
		t.Fatalf("body placement wrong: %s", body)
	}
}

func TestAdminScreensStayUntrackedUnlessIncluded(t *testing.T) {
	_, handler := trackingServer(t, momentoConfig(), nil)
	response := getPage(handler, "/admin/settings")
	if got := response.Header().Get("Content-Security-Policy"); got != shippedPolicy {
		t.Fatalf("admin page policy widened without include_admin: %s", got)
	}
	if strings.Contains(response.Body.String(), "tracker.js") {
		t.Fatal("admin page carried the snippet without include_admin")
	}
	config := momentoConfig()
	config.IncludeAdmin = true
	_, handler = trackingServer(t, config, nil)
	if !strings.Contains(getPage(handler, "/admin/settings").Body.String(), "tracker.js") {
		t.Fatal("include_admin did not track the admin page")
	}
}

func TestNonPageResponsesGetTheNarrowPolicy(t *testing.T) {
	_, handler := trackingServer(t, momentoConfig(), nil)
	for _, path := range []string{"/api/v1/version", "/healthz", "/readyz", "/v1/sys/health", "/api/openapi.json"} {
		response := getPage(handler, path)
		if got := response.Header().Get("Content-Security-Policy"); got != apiPolicy {
			t.Fatalf("%s policy=%q", path, got)
		}
		if strings.Contains(response.Body.String(), "tracker.js") {
			t.Fatalf("%s carried the snippet", path)
		}
	}
	// A static asset is not the shell: no snippet, no nonce, the shipped policy.
	asset := getPage(handler, "/asset.js")
	if asset.Code != http.StatusOK || asset.Header().Get("Content-Security-Policy") != shippedPolicy || strings.Contains(asset.Body.String(), "nonce") {
		t.Fatalf("asset status=%d policy=%q body=%s", asset.Code, asset.Header().Get("Content-Security-Policy"), asset.Body.String())
	}
}

// A settings outage must not take the login screen down with it: the page is
// served without tracking and with the shipped policy.
func TestSettingsOutageServesThePageWithoutTracking(t *testing.T) {
	_, handler := trackingServer(t, momentoConfig(), errors.New(`failed to connect to "host=postgres.internal": SQLSTATE 08006`))
	response := getPage(handler, "/dashboard")
	if response.Code != http.StatusOK || response.Header().Get("Content-Security-Policy") != shippedPolicy {
		t.Fatalf("status=%d policy=%s", response.Code, response.Header().Get("Content-Security-Policy"))
	}
	if strings.Contains(response.Body.String(), "tracker.js") || strings.Contains(response.Body.String(), "postgres.internal") {
		t.Fatalf("outage response wrong: %s", response.Body.String())
	}
}

func TestPolicyReportsAreRecordedOnceAndListedForAdministrators(t *testing.T) {
	server, handler := trackingServer(t, momentoConfig(), nil)
	report := `{"csp-report":{"blocked-uri":"https://pixel.corp.example/p.gif","effective-directive":"img-src","document-uri":"https://jikim.example/dashboard"}}`
	for index := 0; index < 3; index++ {
		response := httptest.NewRecorder()
		request := httptest.NewRequest(http.MethodPost, cspReportPath, strings.NewReader(report))
		request.Header.Set("Content-Type", "application/csp-report")
		handler.ServeHTTP(response, request)
		if response.Code != http.StatusNoContent {
			t.Fatalf("report status=%d", response.Code)
		}
package httpapi

import (
	"context"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"runtime/debug"
	"strings"
	"time"

	"github.com/hkjang/jikim/internal/ids"
	"github.com/hkjang/jikim/internal/model"
	"github.com/hkjang/jikim/internal/store"
	"github.com/hkjang/jikim/internal/tracking"
)

type Server struct {
	store             *store.Store
	logger            *slog.Logger
	httpClient        *http.Client
	aiClient          *http.Client
	static            http.Handler
	loginLimiter      *loginRateLimiter
	aiLimiter         *aiRequestLimiter
	webhookSlots      chan struct{}
	sessionResolver   func(context.Context, string) (model.Session, error)
	sessionRevoker    func(context.Context, string) error
	authenticator     func(context.Context, string, string) (model.User, error)
	securityLoader    func(context.Context) (store.SecurityConfig, error)
	transitAuthorizer func(context.Context, model.User, string, string) (bool, error)
	secretAuthorizer  func(context.Context, model.User, string, string) (bool, error)
	transitEncryptor  func(context.Context, string, string, string) (string, error)
	transitDecryptor  func(context.Context, string, string) (string, error)
	auditRecorder     func(context.Context, model.AuditEvent) error
	storagePinger     func(context.Context) error
	oidcStateOpener   func(string, any) error
	oidcConfigLoader  func(context.Context) (store.OIDCConfig, error)
	trackingLoader    func(context.Context) (tracking.Config, error)
	violations        *tracking.Recorder
	mcpOAuthLoader    func(context.Context) (store.MCPOAuthConfig, error)
	oidcUserFinder    func(context.Context, string, string) (model.User, error)
	oidcCodeConsumer  func(context.Context, string) (string, error)
	userLoader        func(context.Context, string) (model.User, error)
	oauthProviders    oauthProviders

	webhookConfigLoader func(context.Context) (store.WebhookConfig, error)
	webhookCreator      func(context.Context, string, string, string, *string, string, any) (store.WebhookDelivery, error)
	webhookCompleter    func(context.Context, string, int, error) error
}

func New(st *store.Store, logger *slog.Logger) http.Handler {
	if logger == nil {
		logger = slog.Default()
	}
	s := &Server{
		store:        st,
		logger:       logger,
		httpClient:   newOutboundHTTPClient(logger, 30*time.Second),
		aiClient:     newOutboundHTTPClient(logger, 0),
		loginLimiter: newLoginRateLimiter(),
		aiLimiter:    newAIRequestLimiter(),
		webhookSlots: make(chan struct{}, 16),
		violations:   tracking.NewRecorder(),
	}
	s.trackingLoader = st.TrackingConfig
	s.static = discoverStaticHandler(logger, s.decorateIndex)
	mux := http.NewServeMux()
	s.routes(mux)
	return s.requestID(s.recoverer(s.securityHeaders(s.audit(mux))))
}

func (s *Server) routes(mux *http.ServeMux) {
	mux.HandleFunc("GET /healthz", s.health)
	mux.HandleFunc("GET /readyz", s.ready)
	mux.HandleFunc("GET /api/v1/version", s.version)
	mux.HandleFunc("GET /api/v1/capabilities", s.capabilities)
	mux.HandleFunc("GET /api/openapi.json", s.openAPI)
	mux.HandleFunc("GET /api/v1/settings/public", s.publicSettings)
	mux.HandleFunc("GET /api/v1/session", s.sessionStatus)
	mux.HandleFunc("POST /api/v1/auth/login", s.login)
	mux.HandleFunc("GET /api/v1/oidc/config", s.oidcPublicConfig)
	mux.HandleFunc("GET /api/v1/oidc/login", s.oidcLogin)
	mux.HandleFunc("GET /api/v1/oidc/callback", s.oidcCallback)
	mux.HandleFunc("POST /api/v1/oidc/exchange", s.oidcExchange)
	mux.Handle("GET /api/v1/oidc/logout", s.withAuth(http.HandlerFunc(s.oidcLogout)))
