    setupFiles: ['./src/test/setup.ts'],
    coverage: { reporter: ['text', 'html'], include: ['src/lib/**', 'src/components/**'] },
  },
});
name: 오프라인 릴리스

on:
  push:
    tags:
      - 'v*.*.*'
  workflow_dispatch:
    inputs:
      tag:
        description: '새 릴리스 태그(예: v0.2.31). 이미 발행된 릴리스 자산은 덮어쓰지 않습니다.'
        required: true
        default: 'v0.2.31'

permissions:
  contents: write

concurrency:
  group: release-${{ github.event_name == 'workflow_dispatch' && inputs.tag || github.ref_name }}
  cancel-in-progress: false

jobs:
  release:
    name: 이미지 검증 · 패키징 · GitHub Release
    runs-on: ubuntu-latest
    timeout-minutes: 60
    env:
      GH_TOKEN: ${{ github.token }}
    steps:
      - name: 소스 체크아웃
        uses: actions/checkout@v7
        with:
          fetch-depth: 0
          ref: ${{ github.event_name == 'workflow_dispatch' && inputs.tag || github.ref }}

      - name: 릴리스 태그와 소스 버전 일치 확인
        id: version
        shell: bash
        run: |
          expected="$(./scripts/version.sh)"
          if [[ "${GITHUB_EVENT_NAME}" == "workflow_dispatch" ]]; then
            requested="${{ inputs.tag }}"
          else
            requested="${GITHUB_REF_NAME}"
          fi
          if [[ "${requested}" != "${expected}" ]]; then
            printf '태그(%s)와 소스 버전(%s)이 다릅니다.\n' "${requested}" "${expected}" >&2
            exit 1
          fi
          git rev-parse "refs/tags/${requested}" >/dev/null 2>&1 || {
            printf '원격에 존재하는 태그만 릴리스할 수 있습니다: %s\n' "${requested}" >&2
            exit 1
          }
          tag_commit="$(git rev-list -n 1 "refs/tags/${requested}")"
          head_commit="$(git rev-parse HEAD)"
          if [[ "${head_commit}" != "${tag_commit}" ]]; then
            printf '체크아웃 커밋(%s)과 태그 커밋(%s)이 다릅니다.\n' "${head_commit}" "${tag_commit}" >&2
            exit 1
          fi
          printf 'version=%s\n' "${requested}" >> "${GITHUB_OUTPUT}"
          printf 'commit=%s\n' "${head_commit}" >> "${GITHUB_OUTPUT}"

      - name: Go 설정
        uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true

      - name: Node.js 설정
        uses: actions/setup-node@v7
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: web/package-lock.json

      - name: 릴리스 소스 검증
